        "prompt": "25 ℃, 1 atm에서 CO2가 녹아있는 탄산수가 12 L가 있다.\n~~ 게이지압력 7 atm.g에서 1atm(g라는 조건 없음)까지 감소시키는 과정에서 방출된 CO2의 부피는?\n(단, 탄산가스는 이상기체이며 25 ℃, 1 atm에서 CO2은 1.75 g/atm.L만큼 녹아 있다.)",
        "answer": "~~ 게이지압력 7 atm.g에서 1atm(g라는 조건 없음)까지 감소시키는 과정에서 방출된 CO2의 부피는?\n(단, 탄산가스는 이상기체이며 25 ℃, 1 atm에서 CO2은 1.75 g/atm.L만큼 녹아 있다.)\n\n계산과정\n12*1.75*7/44 * 22.4 *(25+273)/27\n\n답\n81.69 L\n\n해설\n1 atm이 게이지압인지 절대압인지 정보가 없는데,\n보통 atm은 절대압으로 본다고는 하지만, 그 앞에 7 atm.g은 게이지압으로 주어졌으므로, 모호하다.\n문제를 출제하다가 단순 오타 탈자가 발생한 사례로 추정이 되지만, 이런 경우는 보통 어떠한 경우로 해도 득점한다.\n여기서는 1 atm은 절대압 즉, 대기압으로 보고 문제를 푼다.\n\n압력 감소로 방출되는 CO2의 질량을 먼저 구하면,\n12 L * 1.75 g/atm.L * 7 atm\n\n질량을 부피로 환산하려면 분자량(44)을 나누어 몰수를 먼저 구한다.\n12*1.75*7/44 몰\n\n25 ℃에서의 이상기체 1몰의 부피는 22.4 *(25+273)/273 L 이므로\n12*1.75*7/44 * 22.4 *(25+273)/27 = 81.69 L",
