        "answer": "(가) 역화의 정의 :\n\n가스의 연소속도가 염공에서의 가스 유출속도보다 크게 됐을 때 불꽃이 버너 내부에 침입하여 노즐 선단 혹은 혼합관에서 연소하는 현상\n\n(나) 역화의 원인\n\nⓐ 가스의 공급압력이 작을 떄\nⓑ 염공이 클 때\n\n참고\n1)   (back fire):\n가스의 연소속도가 염공에서의 가스 유출속도보다 크게 됐을 때 불꽃이 버너 내부에 침입하여 노즐 선단 혹은 혼합관에서 연소하는 현상\n즉, 연료의 분출 속도 < 연소속도\n원인\n① 1차 공기가 적은 경우\n② 공급가스의 압력이 낮을 경우\n③ 염공이 크거나 부식에 의해 확대되었을 경우.\n\n2) 선화 (또는 리프팅, lifting) :\n가스의 공급압력이 높아 불꽃이 염공을 떠나 공간에서 연소하는 현상\n즉, 연료의 분출 속도 > 연소속도\n원인\n① 염공이 작아졌을 때\n② 가스의 공급압력이 높을 때\n③ 배기 또는 환기가 불충분할 때 (2차 공기량 부족)\n④ 공기 조절장치를 지나치게 개방하였을 때 (1차 공기량 과다)\n\n3) 블로우 오프(blow off) :\n불꽃 주위 기류에 의하여 불꽃이 염공에 정착하지 않고 떨어지게 되어 꺼지는 현상\n즉, 연료의 분출 속도 > 연소속도, 주위 공기의 움직임\n원인\n① 염공에서 연료가스의 분출속도가 연소속도보다 클 때\n\n4) 황염(yellow tipping): 노란색 불꽃\n원인\n① 연소반응이 충분한 속도로 진행되지 않을 때\n② 1차 공기량이 부족하여 불완전연소가 발생할 때\n③ 불꽃이 저온의 물체에 접촉하였을 때",
