        "answer": "(단, 외기온도는 20℃, 산소의 비점은 -183℃이다. 액화산소의 기화잠열은 213526 J/kg이다.)\n\n(가) 침입열량 (단위만 잘 보면)\nQ=W*q/(H*△t*V)\n= (250-230) * 213526 / ( 24 * (20--183) * 500 )\n= 1.75 J / h·℃·L\n\n(나) 합격여부\n\n1 J = 0.24 cal = 0.00024 ㎉ 에서\n\n침입열량 = 1.75* 0.00024 = 0.00042 ㎉/h·℃·L\n이므로,\n\n합격\n\n합격기준\n내용적 1000 L 이상: 0.002 ㎉/h·℃·L 이하\n내용적 1000 L 미만: 0.0005 ㎉/h·℃·L 이하",
