        "answer": "(단, B지점은 A지점보다 30 m 위에 있으며, 폴의 정수(K)는 0.7이다.)\n\n(가) 배관의 압력손실\n\n가스 유량식\nQ = K x √{(D^(5) x H)/(S x L)}\n500 = 0.7 √(30^(5)*H/(.65*1000))\n에서 H = 13.65 mmH20\n\n(나) 입상배관의 압력손실\n\nH = 1.293×(S-1)×h = 1.293 * (.65-1)*30 = -13.58 mmH20\n\n(다) B지점 압력\nA지점 공급압력 - 압력손실\n= 200 - (13.65-13.58) = 199.93 mmH20\n\n참고\n가스 유량식\nQ = K√((D^(5)×H /(SL)) (㎥/h)\n여기서\nD : 지름 (㎝)\nS : 가스의 비중\nL : 길이 (m)\nK : 유량계수 (폴의 상수 0.707)\nH : 압력손실 (㎜H2O)\n\n입상관의 압력손실\nH = 1.293×(S-1)×h (mmH2O)\n여기서\nh: 입상 높이, m\nS: 가스의 비중\n참고:가스의 비중의 1보다 작은 경우, 압력손실이 음수(-)로 나타나는데, 이는 압력 증가를 의미",
