        "answer": "(1) 충전용기를 차량에 적재하는 때에는 적재함에 세워서 적재한다.\n(2) 차량의 최대 적재량을 초과하여 적재하지 않는다.\n(3) 차량의 적재함을 초과하여 적재하지 않는다.\n(4) 납붙임용기 및 접합용기에 고압가스를 충전하여 차량에 적재할 때에는 포장 상자의 외면에 가스의 종류·용도 및 취급 시 주의사항을 기재한 것에만 적용하여 적재하고, 그 용기의 이탈을 막을 수 있도록 보호망을 적재함 위에 씌운다.\n(5) 충전용기를 차량에 적재할 때에는 차량운행 중의 동요로 용기가 충돌하지 않도록 고무링을 씌우거나 적재함에 넣어 세워서 적재한다. 다만, 압축가스의 충전용기 중 그 형태 및 운반차량의 구조상 세워서 적재하기 곤란한 때에는 적재함 높이 이내로 눕혀서 적재할 수 있다.\n(6) 충전용기 등을 목재·플라스틱 또는 강철제로 만든 팔레트 내부에 넣어 안전하게 적재하는 경우와 용량 10㎏ 미만의 액화석유가스 충전용기를 적재할 경우를 제외하고 모든 충전용기는 1단으로 쌓는다.\n(7) 충전용기 등은 짐이 무너짐, 떨어짐 또는 차량의충돌 등으로 인한 충격과 밸브의 손상 등을 방지하기 위하여 차량의 짐받이에 바짝 대고로프, 짐을 조이는 공구 또는 그물 등을 사용하여 확실하게 묶어서 적재하며, 운반차량 뒷면에는 두께가 5㎜ 이상, 폭 100㎜ 이상의 범퍼 또는 이와 동등 이상의 효과를 갖는 완충장치를 설치한다.\n(8) 차량에 충전용기 등을 적재한 후 그 차량의 측판 및 뒤판을 정상적인 상태로 닫은 후 확실하게 걸게쇠로 걸어 잠근다.\n(9) 독성가스 중 가연성가스와 조연성가스는 동일 차량 적재함에 운반하지 않는다.\n(10) 밸브가 돌출한 충전용기는 고정식 프로텍터나 캡을 부착하여 밸브의 손상을 방지하는 조치를 한 후 차량에 싣고 운반한다.\n(11) 충전용기를 차에 실을 때에는 넘어지거나 부딛침 등으로 충격을 받지 않도록주의하여 취급하며, 충격을 최소한으로 방지하기 위하여 완충판을 차량 등에 갖추고 이를 사용한다.\n(12) 충전용기는 이륜차(자전거를 포함한다)에 적재하여 운반하지 않는다.  14. 12. 10.>\n(13) 염소와 아세틸렌·암모니아 또는 수소는 동일 차량에 적재하여 운반하지 않는다.\n(14) 가연성가스와 산소를 동일 차량에 적재하여 운반하는 때에는 그 충전용기의 밸브가 서로 마주보지 않도록 적재한다.\n(15) 충전용기와 위험물과는 동일 차량에 적재하여 운반하지 않는다.\n\nKGS GC206\n2.1.2 적재 및 하역 작업\n2.1.2.1 적재",
