        "answer": "(단, 물의 비중량 9.8 kN/m3, 중력가속도 9.8 m/s2, 이산화탄소 기체상수 0.189 kJ/(kg K))\n\n계산과정\n(100+101.325)/(0.189 (273+27))\n------------------------------\n1.2\n\n답\n2.96 (단위 없음)\n\n해설\n1.\n비중은 기준이 되는 물체의 밀도와의 비율이므로,\n우선 밀도를 구하면,\n이상기체 상태방정식를 이용해야 하는데,\n기체상수 R의 단위 0.189 kJ/(kgK) 에 주의하면서 PV= GRT를 이용\n(사실은 주의할 것도 없는 것이, 이미 기체상수가 R가 제시되어 있으므로 그냥 입력만 하면 됨.)\n\n또한 별도의 조건이 없으니, 게이지압력으로 판단하여 대기압 101.325 kPa 를 더하여 절대압력으로 보아,\n\n밀도 ρ = G/V = P / RT\n= (100+101.325)/(0.189 *(27+273))\n= 3.55 kg/m^(3)\n\n2. 그런데, 무엇의 밀도와 비교할 것인가?\n기체는 공기와 비교하고, 액체는 물과 비교한다.\n여기서 문제의 조건이 물의 비중량으로 제시되어,\n출제 의도가 물과의 비교를 하라는 것으로 보이나,\n27℃, 100 kPa 상태의 이산화탄소는 기체다.\n따라서, 공기의 밀도 (1.2 kg/m3) 와 비교해야 하면,\n비중 =  3.55 kg/m^(3) / 1.2 kg/m^(3) = 2.96",
