        "answer": "(단, 수증기의 응축잠열은 0.6 ㎉/g )\n\nH2 (3050 ㎉/㎥) 37 mol%\nO2 1 mol%\nN2 35 mol%\nCO (3030 ㎉/㎥) 5 mol%\nCO2 6 mol%\nCH4 (9540 ㎉/㎥) 6 mol%\nC4H10 (32000 ㎉/㎥) 10 mol%\n\n계산과정\n총발열량\n3050 ㎉/㎥ * 0.37 + 3030 ㎉/㎥* 0.05\n+ 9540 ㎉/㎥* 0.06 + 32000 ㎉/㎥* 0.1 = 5052.4 ㎉/㎥\n\n그러나, 이 안에는 물이 들어가 있고 연소하면 물이 수증기가 되어야 하므로,\n그러한 열량의 손실 (응축잠열)을 빼야 한다.\n\n여기에 관련된 성분은 H가 포함된 아래의 3개로\n\nH2  => H2O\nCH4 => 2 H2O\nC4H10 => 5 H2O\n이만큼이 연소가스 안에서 물 (H20)이 생성된다.\n\n지금 우리는 1 ㎥의 가스에서 얼마나 물이 생성되는지 계산해야 하며\n연료가스 1 ㎥ = 1000/22.4 몰 이며,\n이 연료가스 1 ㎥에서 1*0.37 + 2*0.06 + 5*0.1 = 0.98 ㎥의 물이 생성되니\n(H2O의 분자량 2+16 = 18)\n\n응축잠열 = 0.6 ㎉/g * 1000/22.4*18 g*0.98 = 477.32 ㎉/㎥\n\n따라서,\n진발열량 = 5052.4 ㎉/㎥ - 477.32 ㎉/㎥\n= 4573.08 ㎉/㎥\n",
