        "answer": "[동영상] 위로 곧추선 3줄 PE밸브\n도시가스용 매몰형 폴리에틸렌 플러그밸브 및 매몰형 폴리에틸렌 볼밸브\n\n(1) 최고사용압력이 0.1 ㎫ 일 때 SDR 값은 얼마 이하로 해야 하는가?\n\n21 이하\n\n(2) SDR의 의미를 쓰시오.\n\nSDR (standard dimension ration) = D(외경) / t(최소두께)\n여기서,\nD : PE밸브에 연결되는 배관의 표준외경(㎜)\nt : PE밸브에 연결되는 배관으로써 PE밸브이음매 재질의 강도와 같고, 표준외경 D에서 SDR값이 최소인 배관의 두께(㎜)\n\n참조\nSDR (standard dimension ratio) = D(외경) / t(최소두께)\n11 이하  0.4 ㎫ 이하\n17 이하  0.25 ㎫ 이하\n21 이하  0.2 ㎫ 이하\n\nKGS AA333",
